三、Arduino 設計 

int RBrakes=3; 
int LBrakes=4; 
int Signal=8; 
int moterPower=11; 
int ignition=12; 
int pressureStatus=0; 

void setup() { 
 pinMode(RBrakes,OUTPUT); 
 pinMode(LBrakes,OUTPUT); 
 pinMode(moterPower,OUTPUT); 
 pinMode(ignition,OUTPUT); 
 pinMode(Signal,INPUT); 

 digitalWrite(moterPower,LOW); 
 digitalWrite(RBrakes,LOW); 
 digitalWrite(LBrakes,LOW); 
 digitalWrite(ignition,LOW); 

 delay(3000); 
 digitalWrite(moterPower,HIGH); 

} 

void loop() { 
pressureStatus=digitalRead(Signal); 
if (pressureStatus==1){ 
 delay(20); 
 pressureStatus=digitalRead(Signal); 
 if (pressureStatus==1){ 
 delay(200); 
 digitalWrite(moterPower,LOW); 
 delay(50); 
 digitalWrite(RBrakes,HIGH); 
 digitalWrite(LBrakes,HIGH); 
 digitalWrite(ignition,HIGH); 
 delay(1000); 

 digitalWrite(RBrakes,LOW); 
 digitalWrite(LBrakes,LOW); 
 delay(3000); 
 digitalWrite(ignition,LOW); 
 digitalWrite(moterPower,HIGH); 
 delay(2000); 
 } 
 delay(50); 
 } 
}
